import {TEMP_SOURCES,TEMP_NOTICE,temperatureSettings,plannedStages,stageStatus,temperatureErrors,hydrogenRelative} from './temperature.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(n,d=0)=>Number.isFinite(n)?n.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const kindText={screen:'教学初筛窗',study:'文献案例 / 算域',reserve:'剩余温降倒推',casting:'自定浇注目标',unset:'数值温区待标定'};
const tempVal=n=>Number.isFinite(n)?n:'';
const sourceLink=id=>{const x=TEMP_SOURCES.find(s=>s.id===id);return `<a href="https://doi.org/${x.doi}" target="_blank" rel="noopener noreferrer">${id} · ${x.year} ↗</a>`;};
const rangeText=p=>p.range?`${f(p.range[0])}–${f(p.range[1])} °C`:'待钢种 / 渣系标定';
const configNames={liquidus:'钢种液相线',superheatLow:'目标过热度下限',superheatHigh:'目标过热度上限',transferDrop:'当前站到中间包预计温降',probeT:'试算钢温',pressure:'试算总真空压力',h2Percent:'气相H₂体积分数',fH:'氢活度系数 fH'};
function numberField(t,key,unit,min,max,step=1){return `<label class="temp-field" for="tg-${key}"><span>${configNames[key]} · ${unit}</span><input id="tg-${key}" type="number" data-tconfig="${key}" value="${tempVal(t[key])}" min="${min}" max="${max}" step="${step}"></label>`;}
function planInput(p,prefix){return `<label class="temp-field temp-plan"><span class="sr-only">${esc(p.moduleName+' / '+p.name)}计划参考温度 / °C</span><input type="number" data-phase-t="${esc(p.key)}" aria-label="${esc(p.moduleName+' / '+p.name)}计划参考温度 / °C" min="1300" max="1850" step="1" value="${tempVal(p.T)}"><small>计划值 / °C</small></label>`;}
export function mountTemperatureGuide({getState,persist,openStage}){let mounted=false;
 function inputBlock(){const s=getState(),t=temperatureSettings(s);return `<div class="temperature-body"><div class="temp-boundary"><strong>最佳温度不是设备常数。</strong><p>${TEMP_NOTICE}</p><p>橙色“教学初筛窗”是方案核对的示例，不是论文认证窗口；绿色也只表示处于所示范围，不表示反应达到平衡或牌号合格。</p></div><div class="temp-section-head"><h3>先定义浇注约束</h3><a href="./heating.html">打开加热与热损失评定 ↗</a></div><div class="temp-config-grid">${numberField(t,'liquidus','°C',1300,1600)}${numberField(t,'superheatLow','°C',0,100)}${numberField(t,'superheatHigh','°C',0,100)}${numberField(t,'transferDrop','°C',0,150)}</div><p class="temp-small">液相线默认1500°C仅是占位示例，切换钢种不会自动由成分求得液相线。每一段填写独立计划温度；这些数值不是沿工序计算出的实际温降。</p><div id="temp-config-error" class="temp-config-error" role="alert" hidden></div><div class="temp-section-head"><h3>沿流程，按元素查看温度条件</h3><div id="temp-filter" class="temp-filter" role="group" aria-label="按关注元素筛选"></div></div><div id="temp-stage-table" class="table-wrap"></div><div id="temp-summary" class="temp-summary"></div><section class="temp-h-panel"><div class="temp-section-head"><h3>VD示例：为什么温度越高不一定越利于脱氢？</h3><span class="pill">T04 · 平衡趋势演示</span></div><p class="temp-small">用同一平衡关系比较温度、氢分压和活度系数的影响。以1600°C、pH₂=6.6 Pa、fH=1为人为选定的归一化基准；只显示相对比值，不预测最终H含量。</p><div class="temp-config-grid">${numberField(t,'probeT','°C',1400,1800)}${numberField(t,'pressure','Pa',.1,10000,.1)}${numberField(t,'h2Percent','%',0,100,.1)}${numberField(t,'fH','无量纲',.01,100,.01)}</div><div id="temp-h-output"></div></section><div class="temp-section-head"><h3>如何判断“热力学最佳”？</h3></div><div class="temp-principles"><article><b>ΔG = ΔG°(T) + RT ln Q</b><p>必须给出钢液/渣活度、气体分压及目标约束，才能讨论平衡；仅有温度不能计算最优点。</p></article><article><b>脱P与脱S的渣条件不同</b><p>P主要在氧化早期去除；LF脱S需要低氧还原渣。高温不能替代正确的氧势与碱度。</p></article><article><b>溶解O不等于总氧T.O</b><p>脱氧生成夹杂后，还要传质和上浮；降温有利某些平衡，也可能析出新夹杂。</p></article><article><b>N与合金元素需单独求解</b><p>pN₂、Cr/Al/Ti活度及吸脱氮动力学共同作用。当前不预测N的温度效应，也不计算Cr、Si、Mn收得率。</p></article></div><h3 class="temp-evidence-title">温度证据索引 · 独立于原料耗数据</h3><div class="temp-source-grid">${TEMP_SOURCES.map(x=>`<article><span>${x.id} / ${x.year}</span><h4>${x.title}</h4><p>${x.note}</p>${sourceLink(x.id)}</article>`).join('')}</div></div>`;}
 function table(){const s=getState(),t=temperatureSettings(s),rows=plannedStages(s).filter(p=>t.filter==='all'||p.elements.includes(t.filter));document.querySelector('#temp-filter').innerHTML=['all','P','S','H','C','O','Cr','Ca','T.O'].map(k=>`<button class="${t.filter===k?'active':''}" data-tfilter="${k}" aria-pressed="${t.filter===k}">${k==='all'?'全部':k}</button>`).join('');
 document.querySelector('#temp-stage-table').innerHTML=`<table class="data-table temperature-table"><thead><tr><th>设备 / 子步骤</th><th>关注元素</th><th>温度参考与性质</th><th>计划参考温度</th><th>热力学方向 / 条件</th><th>论文与边界</th></tr></thead><tbody>${rows.map(p=>`<tr data-trow="${esc(p.key)}"><td><strong>${esc(p.moduleName)}</strong><p>${esc(p.name)}</p>${p.moduleId==='casting'?'':`<button class="text-button" data-topen="${esc(p.moduleId)}">定位设备 →</button>`}</td><td>${p.elements.map(e=>`<span class="temp-element">${esc(e)}</span>`).join('')}</td><td><strong data-trange="${esc(p.key)}">${rangeText(p)}</strong><small class="temp-kind ${p.kind}">${kindText[p.kind]}</small></td><td>${planInput(p,'table')}<span data-tstatus="${esc(p.key)}"></span></td><td class="wrap"><strong>${esc(p.direction)}</strong><p>${esc(p.condition)}</p></td><td class="wrap">${esc(p.reference)}<div class="temp-links">${p.refs.map(sourceLink).join(' ')}</div></td></tr>`).join('')||'<tr><td colspan="6">当前路线没有该元素的温度说明；可在设备库添加相应工序。</td></tr>'}</tbody></table>`;}
 function editor(){document.querySelectorAll('.temperature-mini').forEach(e=>e.remove());const s=getState(),t=temperatureSettings(s),rows=plannedStages(s).filter(p=>p.moduleId===s.selected);const anchor=document.querySelector('#editor .editor-intro');if(!anchor||!rows.length)return;anchor.insertAdjacentHTML('afterend',`<section class="temperature-mini" aria-label="本工序温度与元素"><div class="temp-mini-title"><strong>温度与元素</strong><button class="text-button" data-go="temperature">查看完整温度表 →</button></div>${rows.map(p=>`<div class="temp-mini-row"><div><b>${esc(p.name)}</b><p>${p.elements.join(' / ')} · <span data-trange="${esc(p.key)}">${rangeText(p)}</span></p><small>${kindText[p.kind]}</small></div>${planInput(p,'editor')}<div class="temp-mini-status" data-tstatus="${esc(p.key)}"></div><p class="temp-mini-direction">${esc(p.direction)}</p></div>`).join('')}<p class="temp-mini-disclaimer">仅核对温度条件；不会改变当前成分估算。</p></section>`);}
 function updateValues(){const s=getState(),t=temperatureSettings(s),errors=temperatureErrors(t),rows=plannedStages(s),active=document.activeElement;const error=document.querySelector('#temp-config-error');error.hidden=!errors.length;error.textContent=errors.map(msg=>Object.entries(configNames).reduce((v,[k,name])=>v.replace(k,name),msg)).join('；');
 for(const p of rows){document.querySelectorAll('[data-phase-t]').forEach(el=>{if(el.dataset.phaseT===p.key&&el!==active)el.value=tempVal(p.T);});document.querySelectorAll('[data-trange]').forEach(el=>{if(el.dataset.trange===p.key)el.textContent=errors.length&&['reserve','casting'].includes(p.kind)?'浇注条件无效':rangeText(p);});const status=errors.length?{className:'warn',text:'请修正计算条件'}:stageStatus(p,t);document.querySelectorAll('[data-tstatus]').forEach(el=>{if(el.dataset.tstatus===p.key){el.className='temp-status '+status.className;el.textContent=status.text;}});}
 const warnings=rows.filter(p=>stageStatus(p,t).className==='warn').length;document.querySelector('#temp-summary').innerHTML=errors.length?'请先修正液相线或过热度等输入。':`当前 ${rows.length} 个子步骤，${warnings} 项温度提示。浇注前目标 <strong>${f(t.liquidus+t.superheatLow)}–${f(t.liquidus+t.superheatHigh)}°C</strong>；当前站若还将损失${f(t.transferDrop)}°C，则储备目标为 <strong>${f(t.liquidus+t.superheatLow+t.transferDrop)}–${f(t.liquidus+t.superheatHigh+t.transferDrop)}°C</strong>。这些是用户约束，不是元素反应的统一最佳温度。`;
 const x=hydrogenRelative(t.probeT,t.pressure,t.h2Percent/100,t.fH);document.querySelector('#temp-h-output').innerHTML=!x||errors.length?'<p class="temp-small">请修正试算温度、压力、H₂占比或活度系数。</p>':`<div class="temp-h-result"><div><small>当前pH₂ = 总压 × H₂占比</small><strong>${f(x.partialPa,2)} <span>Pa</span></strong></div><div><small>相对基准的H平衡值</small><strong>${f(x.ratio,3)} <span>倍</span></strong></div><div><small>仅改变温度（其他条件固定）</small><strong>${f(hydrogenRelative(t.probeT,66,.1,1).ratio,3)} <span>倍</span></strong></div></div><div class="temp-h-compare">${[1550,1600,1650].map(T=>`<span>${T}°C → <b>${f(hydrogenRelative(T,66,.1,1).ratio,3)}×</b></span>`).join('')}</div><div class="temp-formula">[%H]eq = (K/fH)√(pH₂/p°)，log₁₀K = −1670/T − 1.68，T = °C + 273.15。<br>归一化H/H基准 = 10^[−1670(1/T−1/1873.15)] × √(pH₂/6.6 Pa) / fH。</div><p class="temp-small">提高温度时，同气氛和活度条件的平衡H值增加；降低pH₂则降低平衡H值。本演示只计算比值，参考压力约定在归一化中抵消。fH=1是示例，不锈钢尤其需按成分修正；数值不回写原H代理模型。</p>`;
 }
 function refresh(){const root=document.querySelector('#temperature-guide');if(!root)return;temperatureSettings(getState());root.innerHTML=inputBlock();table();editor();updateValues();mounted=true;persist();}
 document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.phaseT&&!el.dataset.tconfig)return;const t=temperatureSettings(getState());if(el.dataset.phaseT)t.temps[el.dataset.phaseT]=el.valueAsNumber;if(el.dataset.tconfig)t[el.dataset.tconfig]=el.valueAsNumber;updateValues();persist();});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const t=temperatureSettings(getState());if(b.dataset.tfilter){t.filter=b.dataset.tfilter;table();updateValues();persist();}if(b.dataset.topen)openStage(b.dataset.topen);});
 refresh();return{refresh,updateValues};
}
